const icon=(name)=>{const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',list:'M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1',machine:'M4 5h16v12H4z M8 21v-4M16 21v-4M8 9h3M15 9h1M8 13h8',calendar:'M4 5h16v16H4z M4 10h16M8 3v4M16 3v4',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.9',tag:'M3 3h8l10 10-8 8L3 11zM7 7h.01',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M13 6l6 6-6 6',logout:'M9 3H4v18h5M9 12h12M16 7l5 5-5 5',clock:'M12 8v4l3 2M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',lock:'M5 10h14v11H5zM8 10V7a4 4 0 0 1 8 0v3'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.grid).split(/(?=M)/).map(d=>`<path d="${d}"/>`).join('')}</svg>`;};
function localDate(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function addDays(date,n){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
function fmt(value){if(!value)return 'Non pianificata';const source=String(value),date=new Date(/[zZ]$|[+-]\d{2}:?\d{2}$/.test(source)?source:source+'Z');return new Intl.DateTimeFormat('it-IT',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'UTC'}).format(date);}
function mins(n){return n<60?`${n} min`:`${Math.floor(n/60)} h${n%60?' '+n%60+' min':''}`;}
function machine(id){return state.machines.find(m=>m.id===id);}
function type(id){return state.types.find(t=>t.id===id);}
function badge(status){return `<span class="badge ${status}">${status==='in_progress'?'<i></i>':''}${labels[status]}</span>`;}
function options(items,value,empty){return `${empty?`<option value="">${empty}</option>`:''}${items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)}</option>`).join('')}`;}
function toast(message,error=false){if(error&&modal.open){const box=$('.dialog-error',modal);if(box){box.hidden=false;box.textContent=message;}}const t=$('#toast');t.textContent=message;t.className='visible'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',6000);}
async function api(url,data){const r=await fetch('/api/'+url,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-Aloven-Request':'1'}:{},body:data?JSON.stringify(data):undefined});const result=await r.json();if(!r.ok){if(r.status===401&&state){modal.close();state=null;await boot();}throw new Error(result.error||'Operazione non riuscita.');}return result;}
function formFingerprint(form){return JSON.stringify([...new FormData(form)].map(([name,value])=>[name,value instanceof File?`${value.name}:${value.size}:${value.lastModified}`:value]));}
function openDialog(html,handler,{protectUnsaved=false,onDiscard=null}={}){modal._detailRequest=null;modal.onclick=modal.oninput=modal.onchange=modal.onkeydown=modal.oncancel=null;modal.innerHTML=html;modal.firstElementChild?.insertAdjacentHTML('afterend','<div class="dialog-error" role="alert" hidden></div>');modal.showModal();if($('[name="productArticleId"]',modal)&&$('[name="machineId"]',modal))enhanceTaskMachineForm();const form=$('form',modal);let pending=false,initial=null;const requestClose=()=>{if(pending)return;if(protectUnsaved&&form&&initial!==null&&formFingerprint(form)!==initial&&!confirm('Hai modifiche non salvate. Vuoi chiudere senza salvarle?'))return;modal.close();onDiscard?.();};modal._requestClose=requestClose;modal.oncancel=e=>{e.preventDefault();requestClose();};$('[data-close]',modal)?.addEventListener('click',requestClose);if(!form)return;queueMicrotask(()=>{if(form.isConnected)initial=formFingerprint(form);});if(handler)form.addEventListener('submit',async e=>{e.preventDefault();if(pending)return;const data=new FormData(e.target);pending=true;const controls=[...form.querySelectorAll('button,input,select,textarea')],disabled=controls.map(control=>control.disabled),error=$('.dialog-error',modal);if(error){error.hidden=true;error.textContent='';}form.setAttribute('aria-busy','true');controls.forEach(control=>control.disabled=true);try{await handler(data);}catch(err){toast(err.message,true);}finally{pending=false;if(form.isConnected){form.removeAttribute('aria-busy');controls.forEach((control,index)=>control.disabled=disabled[index]);}}});}
function dialogHeader(title,subtitle=''){return `<div class="dialog-heading"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button type="button" class="icon-button" data-close aria-label="Chiudi">×</button></div>`;}
function dialogFooter(label='Salva'){return `<div class="dialog-footer"><button type="button" class="button secondary" data-close-bottom>Annulla</button><button class="button primary" type="submit">${label}</button></div>`;}
modal.addEventListener('click',e=>{if(e.target.closest('[data-close-bottom]')){if(modal._requestClose)modal._requestClose();else modal.close();}});
function stateEndpoint(){return view==='planning'?'state?view=planning'+(showCompleted?'&includeCompleted=1':''):view==='shopfloor'?'state?view=shopfloor':'state';}
async function reload(){const table=$('.table-wrap'),tableScroll=table?{left:table.scrollLeft,top:table.scrollTop}:null;state=await api(stateEndpoint());render();if(tableScroll&&$('.table-wrap')){$('.table-wrap').scrollLeft=tableScroll.left;$('.table-wrap').scrollTop=tableScroll.top;}}
async function mutate(action,forceConfirm=false,directDraft=false,preparedPreview=null){
  const previousTask=action.kind==='plan'?state.tasks.find(t=>t.id===action.id):null;const undoView={taskId:action.id,date:previousTask?.start?.slice(0,10)||dateStart,machineId:previousTask?.machineId};
  const returnToSequence=sequenceReturn;sequenceReturn=null;
  const collection={task:'tasks',machine:'machines',type:'types',article:'articles',setupRule:'setupRules'}[action.kind];const previousIds=collection&&!action.id&&!action.remove?new Set(state[collection].map(x=>x.id)):null;
  const preview=preparedPreview||await api('preview',{revision:state.revision,action});
  if(action.shiftFollowing&&!Array.isArray(preview.placements))throw new Error('Il server deve essere aggiornato per spostare la coda. Riavvia Aloven e ricarica la pagina.');
  if(action.fixedStart&&(preview.placement?.fixedStart!==action.fixedStart||preview.placement?.start!==action.fixedStart))throw new Error('Il server non supporta ancora la data scelta. Riavvia Aloven e aggiorna la pagina.');
  const warnings=preview.warnings||[];
  const needsConfirm=warnings.length>0||(!directDraft&&(forceConfirm||preview.changes.some(x=>x.oldStart)));
  const commit=async()=>{const result=await api('commit',{token:preview.token,...(view==='planning'?{includeState:action.kind==='plan'?'planning':'planner',includeCompleted:showCompleted,plannerProjection:true}:{})});lastPlanUndo=result.undo?{...result.undo,...undoView}:null;modal.close();if(action.kind==='maintenance'&&view==='planning'){selectedTaskId=null;resetTimeScroll();if(!action.remove){const date=action.start.slice(0,10);if(date<dateStart||date>=addDays(dateStart,planDays))dateStart=date;}}if(action.kind==='plan'&&view==='planning'&&action.fixedStart)selectedTaskId=null;if(action.fixedStart){const date=action.fixedStart.slice(0,10);if(date<dateStart||date>=addDays(dateStart,planDays))dateStart=date;}if(result.planningState&&view==='planning'){const updated=new Map(result.planningState.tasks.map(task=>[task.id,task]));state={...state,...result.planningState,tasks:state.tasks.map(task=>updated.get(task.id)||task)};render();}else if(result.state&&view==='planning'){state=result.state;render();}else await reload();if(action.fixedStart)revealPlannedTask(action.id);if(previousIds&&view===collection&&!search&&(view!=='tasks'||(!statusFilter&&!machineFilter))){const index=state[collection].findIndex(x=>!previousIds.has(x.id));if(index>=0){listPage=Math.floor(index/listSize);render();const control=document.querySelector('[data-edit="'+action.kind+':'+state[collection][index].id+'"]');control?.scrollIntoView({block:'nearest',inline:'nearest'});control?.focus();}}toast(directDraft?'Bozza aggiornata. Rilascia il piano per inviarla al reparto.':'Modifiche salvate.');if(returnToSequence&&view==='planning')sequenceDialog(returnToSequence.machineId,returnToSequence);};
  if(!needsConfirm){await commit();return;}
  modal.close();
  const maintenance=preview.maintenance;
  const maintenanceSummary=maintenance?`<div class="maintenance-preview"><strong>${esc(maintenance.block.name)}</strong><p>${esc(machine(maintenance.block.machineId)?.name)} · ${fmt(maintenance.block.start)} → ${fmt(maintenance.block.end)}</p><p>${action.remove?'Il blocco sarà rimosso.':'La macchina sarà indisponibile in questo intervallo.'} Salvataggio in bozza; il piano al reparto cambia solo al rilascio.</p></div>`:'';
  openDialog(`${dialogHeader(action.kind==='maintenance'?'Conferma indisponibilità':'Conferma la modifica',preview.changes.length?'Verifica le nuove date prima di salvare la bozza.':'Le altre attività mantengono le date attuali.')}<form><div class="dialog-body">${previousTask?.fixedStart&&!Object.hasOwn(action,'fixedStart')&&!action.unplan?`<p class="notice">La data fissata di ${esc(previousTask.title)} sarà rimossa: le nuove date seguiranno la sequenza.</p>`:''}${action.shiftFollowing?'<p class="notice">Stai inserendo l’attività alla data scelta e spostando le successive sulla risorsa. Gli altri inizi fissati restano protetti.</p>':''}${maintenanceSummary}${warnings.length?`<section class="notice" role="alert"><strong>Verifica i dati della lavorazione</strong><ul>${warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul><p>Conferma e salva solo se questi dati sono intenzionali.</p></section>`:''}${preview.changes.length?`<div class="change-list">${preview.changes.map(c=>`<div><strong>${esc(c.title)}</strong><p>${fmt(c.oldStart)} → <b>${fmt(c.start)}</b></p><small>Fine: ${fmt(c.oldEnd)} → ${fmt(c.end)}</small>${durationChanges(c)}</div>`).join('')}</div>`:action.kind==='maintenance'?'<p>Nessuna attività deve cambiare data.</p>':'<p>Confermi questa operazione?</p>'}<p class="notice">L’anteprima è valida per 5 minuti. Le attività in corso e completate restano bloccate.</p></div>${dialogFooter('Conferma e salva')}</form>`,commit,{onDiscard:returnToSequence?()=>sequenceDialog(returnToSequence.machineId,returnToSequence):null});
}
async function boot(){try{const s=await api('session');if(!s.user){renderAuth(s.needsSetup);return;}await reload();}catch(e){app.innerHTML=`<div class="loading">${esc(e.message)}<button class="button" id="retry">Riprova</button></div>`;$('#retry').onclick=boot;}}
function renderAuth(setup){clearTimeTips();app.innerHTML=`<div class="auth-layout"><section class="auth-brand"><div class="brand">${icon('machine')} ALOVEN<span>PRODUZIONE</span></div><div><p class="eyebrow">IL TEMPO, AL POSTO GIUSTO</p><h1>Ogni macchina.<br>Una sequenza chiara.</h1><p>Accoppiati tessili, materiali e calendari di lavoro<br>in un unico piano di produzione.</p><div class="auth-sequence"><span>Attrezzaggio</span><span>Produzione</span><span>Prossima attività</span></div></div><small>Pianificazione della produzione · Europe/Rome</small></section><section class="auth-form"><form id="auth"><p class="eyebrow">${setup?'PRIMO ACCESSO':'BENTORNATO'}</p><h2>${setup?'Configura il tuo reparto':'Accedi ad Aloven'}</h2><p>${setup?'Crea il primo account amministratore. Potrai poi aggiungere gli altri utenti.':'Accedi con le credenziali del tuo reparto.'}</p>${setup?'<label>Nome e cognome<input name="name" required maxlength="200" autocomplete="name"></label>':''}<label>Nome utente<input name="username" required maxlength="80" autocomplete="username"></label><label>Password<input name="password" type="password" required ${setup?'minlength="10"':''} maxlength="200" autocomplete="${setup?'new-password':'current-password'}"></label>${setup?'<small>Almeno 10 caratteri.</small>':''}<p id="auth-error" role="alert"></p><button class="button primary" type="submit">${setup?'Crea amministratore':'Accedi'} ${icon('arrow')}</button></form></section></div>`;
$('#auth').onsubmit=async e=>{e.preventDefault();const b=$('button',e.target);b.disabled=true;try{await api(setup?'setup':'login',Object.fromEntries(new FormData(e.target)));await reload();}catch(err){$('#auth-error').textContent=err.message;}finally{b.disabled=false;}};}
const nav=[['planning','Pianificazione','grid'],['shopfloor','Bordo macchina','machine'],['statistics','Statistiche','list'],['tasks','Attività','list'],['machines','Macchine','machine'],['types','Tipologie lavorazione','tag'],['articles','Articoli','tag'],['setupRules','Attrezzaggi','clock'],['scrapReasons','Causali scarto','tag'],['machineStopReasons','Causali fermo','tag'],['calendar','Calendario','calendar'],['users','Utenti','users']];
nav.push(['traceability','Tracciabilità','tag'],['quality','Verifiche qualità','tag'],['audit','Registro modifiche','list'],['backups','Backup','clock']);
const mesViews=['traceability','quality','audit','backups'];
const navigationGroups={catalogues:{label:'Anagrafiche',icon:'tag',ids:['machines','articles','types','setupRules','scrapReasons','machineStopReasons']},settings:{label:'Configurazione',icon:'clock',ids:['calendar','users','audit','backups']}};
const lastGroupView={catalogues:'machines',settings:'calendar'};
function currentNavigationGroup(){return Object.keys(navigationGroups).find(key=>navigationGroups[key].ids.includes(view));}
function primaryNavigation(){const group=currentNavigationGroup();return [['planning','Pianificazione','grid'],['tasks','Attività','list'],['shopfloor','Bordo macchina','machine'],['statistics','Statistiche','list']].map(([id,label,ico])=>`<button data-nav="${id}" class="${(view===id||(id==='tasks'&&['traceability','quality'].includes(view)))?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}${label}</button>`).join('')+Object.entries(navigationGroups).map(([key,g])=>`<button data-nav-group="${key}" class="${group===key?'active':''}" ${group===key?'aria-current="page"':''}>${icon(g.icon)}${g.label}</button>`).join('');}
function secondaryNavigation(){if(['tasks','traceability','quality'].includes(view))return `<nav class="section-navigation" aria-label="Attività e controllo produzione">${[['tasks','Lavorazioni'],['traceability','Tracciabilità'],['quality','Verifiche qualità']].map(([id,label])=>`<button data-mes-nav="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`;const key=currentNavigationGroup();if(!key)return '';const group=navigationGroups[key];return `<nav class="section-navigation" aria-label="${group.label}">${nav.filter(([id])=>group.ids.includes(id)&&(!['users','audit','backups'].includes(id)||state.user.role==='admin')).map(([id,label])=>`<button data-nav="${id}" class="${(view===id||(id==='tasks'&&['traceability','quality'].includes(view)))?'active':''}" ${view===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`;}
function render(){if(!state)return;listTotal=null;const oldScroll=$('.timeline-scroll'),scroll=oldScroll?{left:oldScroll.scrollLeft,top:oldScroll.scrollTop}:null,oldContent=$('.console-content'),contentScroll=oldContent?{left:oldContent.scrollLeft,top:oldContent.scrollTop}:null,active=document.activeElement,focusSelector=active&&app.contains(active)?active.id?`#${CSS.escape(active.id)}`:['edit','detail','delete'].map(key=>active.dataset?.[key]?`[data-${key}="${CSS.escape(active.dataset[key])}"]`:null).find(Boolean):null;clearTimeTips();if(view==='shopfloor'){app.innerHTML=shopfloorView(shopContext());bindShopfloor(shopContext());return;}const title=nav.find(x=>x[0]===view)?.[1];app.innerHTML=`<div class="shell" data-revision="${state.revision}"><aside class="sidebar"><a class="brand" href="/">${icon('machine')} ALOVEN<span>PRODUZIONE</span></a><p class="nav-caption">REPARTO PRODUTTIVO</p><nav aria-label="Menu principale">${primaryNavigation()}</nav><div class="sidebar-bottom"><div class="live-dot">Dati caricati</div><div class="user"><span class="avatar">${esc(state.user.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(state.user.name)}</strong><small>${state.user.role==='admin'?'Amministratore':'Operatore'}</small></div><button id="logout" class="icon-button" aria-label="Esci">${icon('logout')}</button></div></div></aside><main class="${view==='planning'?'planning-main':''}"><header class="topbar"><span>Reparto <span class="slash">/</span> ${title}</span><div><span class="today">${new Intl.DateTimeFormat('it-IT',{dateStyle:'full',timeZone:'Europe/Rome'}).format(new Date())}</span><button class="button subtle" id="refresh">↻ Aggiorna</button></div></header><div class="workspace ${view==='planning'?'planning-workspace':''}">${secondaryNavigation()}${view==='planning'?planning():view==='statistics'?statisticsView(statisticsContext()):mesViews.includes(view)?mesView(mesContext()):view==='calendar'?calendarView():['scrapReasons','machineStopReasons'].includes(view)?reasonCatalogView():['articles','setupRules'].includes(view)?advancedView():entityView()}${listPagination()}</div></main></div>`;finishConsoleLayout();bindCommon();if(view==='planning'){bindPlanning();if(scroll&&$('.timeline-scroll')){$('.timeline-scroll').scrollLeft=scroll.left;$('.timeline-scroll').scrollTop=scroll.top;}}else if(view==='statistics')bindStatistics(statisticsContext());else if(mesViews.includes(view))bindMes(mesContext());else if(view==='calendar')bindCalendar();else if(['scrapReasons','machineStopReasons'].includes(view))bindReasonCatalog();else bindEntities();if(contentScroll&&$('.console-content')){$('.console-content').scrollLeft=contentScroll.left;$('.console-content').scrollTop=contentScroll.top;}if(focusSelector)$(focusSelector)?.focus({preventScroll:true});}
function pageItems(items){listTotal=items.length;listPage=Math.min(listPage,Math.max(0,Math.ceil(listTotal/listSize)-1));return items.slice(listPage*listSize,(listPage+1)*listSize);}
function renderListPage(selector){render();const control=$(selector);if(control&&!control.disabled)control.focus();else $('.list-pagination')?.focus();}
function listPagination(){if(listTotal===null)return '';const pages=Math.max(1,Math.ceil(listTotal/listSize));return `<footer class="list-pagination" tabindex="-1" aria-label="Paginazione elenco"><span role="status">${listTotal?listPage*listSize+1:0}–${Math.min((listPage+1)*listSize,listTotal)} di ${listTotal} elementi</span><label>Righe<select id="list-size" aria-label="Righe per pagina">${[25,50,100].map(n=>`<option value="${n}" ${listSize===n?'selected':''}>${n}</option>`).join('')}</select></label><button id="list-previous" class="button secondary" ${listPage===0?'disabled':''}>Precedente</button><span>${listPage+1} / ${pages}</span><button id="list-next" class="button secondary" ${listPage>=pages-1?'disabled':''}>Successiva</button></footer>`;}
function finishConsoleLayout(){if(view==='planning')return;const root=$('.workspace');root.classList.add('console-workspace');root.dataset.view=view;const content=document.createElement('div');content.className='console-content';if(!['calendar','statistics'].includes(view))content.classList.add('list-content');for(const child of [...root.children])if(!child.classList.contains('page-heading')&&!child.classList.contains('section-navigation'))content.append(child);root.append(content);for(const wrap of content.querySelectorAll('.table-wrap')){wrap.tabIndex=0;wrap.setAttribute('aria-label','Elenco '+(nav.find(n=>n[0]===view)?.[1]||'dati'));}}
function heading(title,desc,button=''){return `<div class="page-heading"><div><p class="eyebrow">ALOVEN / PRODUZIONE</p><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${button}</div>`;}
function bindCommon(){ $('#list-size')?.addEventListener('change',e=>{listSize=Number(e.target.value);listPage=0;renderListPage('#list-size');});$('#list-previous')?.addEventListener('click',()=>{listPage--;renderListPage('#list-previous');});$('#list-next')?.addEventListener('click',()=>{listPage++;renderListPage('#list-next');});document.querySelectorAll('[data-nav-group]').forEach(b=>b.onclick=async()=>{const previousScope=view==='planning'?'planning':view==='shopfloor'?'shopfloor':'full';view=lastGroupView[b.dataset.navGroup];listPage=0;search='';if(previousScope!==(view==='planning'?'planning':view==='shopfloor'?'shopfloor':'full'))await reload();else render();window.scrollTo(0,0);});document.querySelectorAll('[data-nav],[data-mes-nav]').forEach(b=>b.onclick=async()=>{if(b.dataset.nav==='shopfloor'){location.href='/bordo-macchina';return;}const previousScope=view==='planning'?'planning':view==='shopfloor'?'shopfloor':'full';view=b.dataset.nav||b.dataset.mesNav;listPage=0;const group=currentNavigationGroup();if(group)lastGroupView[group]=view;search='';if(previousScope!==(view==='planning'?'planning':view==='shopfloor'?'shopfloor':'full'))await reload();else render();window.scrollTo(0,0);});$('#logout').onclick=async()=>{await api('logout',{});state=null;await boot();};$('#refresh').onclick=()=>reload().catch(e=>toast(e.message,true));document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>editEntity(b.dataset.new));}
const materialFields=['component1Code','component1Description','component2Code','component2Description','productCode','productDescription'];
function matchesTask(t,query){const q=query.trim().toLocaleLowerCase('it');return !q||[t.title,t.outputLot,t.orderReference,t.erpReference,t.customer,...materialFields.map(f=>t[f])].some(v=>String(v||'').toLocaleLowerCase('it').includes(q));}
function materialFlow(t){return t.productCode?`<div class="material-flow"><div><span title="${esc(t.component1Description)}">${esc(t.component1Code)}</span><b>+</b><span title="${esc(t.component2Description)}">${esc(t.component2Code)}</span></div><p><span aria-hidden="true">↳</span><strong>${esc(t.productCode)}</strong></p><small>${esc(t.productDescription)}</small>${quantityCaption(t)}</div>`:'<div class="materials-missing">Componenti e articolo da completare</div>';}
function materialDetails(t){return `<section class="material-details"><h3>Componenti consumati → Articolo prodotto</h3>${[['component1','Componente 1'],['component2','Componente 2'],['product','Articolo prodotto']].map(([prefix,label])=>`<div class="${prefix==='product'?'product-row':''}"><span>${label}</span><strong>${esc(t[prefix+'Code']||'Da specificare')}</strong><p>${esc(t[prefix+'Description']||'Descrizione da specificare')}</p></div>`).join('')}</section>`;}
function materialForm(x){return `<section class="material-form"><h3>Componenti consumati</h3><div class="form-grid">${[1,2].map(i=>`<label>Componente ${i}<select aria-label="Componente ${i}" name="component${i}ArticleId" required>${articleOptions(x['component'+i+'ArticleId'],'component')}</select></label>`).join('')}</div><p class="notice">Codici e descrizioni provengono dall’anagrafica Articoli. Nessuna movimentazione di magazzino.</p></section>`;}
function revealPlannedTask(id){
  if(view!=='planning')return;
  const area=$('.timeline-scroll'),block=[...document.querySelectorAll('.time-block')].find(b=>b.dataset.task===id);
  if(!area||!block)return;
  const bounds=area.getBoundingClientRect(),rect=block.getBoundingClientRect(),header=block.closest('.gantt-row')?.querySelector('.temporal-machine').getBoundingClientRect();
  const left=(header?.right??bounds.left)+8,right=bounds.right-16,top=bounds.top+($('.gantt-dates',area)?.offsetHeight||0)+8,bottom=bounds.bottom-16;
  if(rect.left<left)area.scrollLeft-=left-rect.left;
  else if(rect.right>right)area.scrollLeft+=Math.min(rect.right-right,rect.left-left);
  if(rect.top<top)area.scrollTop-=top-rect.top;
  else if(rect.bottom>bottom)area.scrollTop+=Math.min(rect.bottom-bottom,rect.top-top);
}
function resetTimeScroll(){const area=$('.timeline-scroll');if(area)area.scrollLeft=0;}
let dragSavePending=false;
