  const reference=[t.productCode,t.orderReference&&`Ordine ${t.orderReference}`].filter(Boolean).join(' · '),tooltip=[t.title,t.productCode,t.productDescription,t.orderReference&&`Ordine ${t.orderReference}`].filter(Boolean).join(' · '),alternative=t.machineId!==selectedResourceId;
