function sequenceRow(t,index,queue,ds){
  const locked=['in_progress','completed'].includes(t.status),firstMovable=queue.findIndex(x=>!['in_progress','completed'].includes(x.status));
  const upDisabled=locked||index<=Math.max(0,firstMovable),downDisabled=locked||index===queue.length-1;
  const pendingRequest=(state.interruptionRequests||[]).some(r=>r.taskId===t.id&&r.status==='requested');
  const article=state.articles?.find(a=>a.id===t.productArticleId),quantity=t.quantity==null?'—':`${esc(new Intl.NumberFormat('it-IT').format(t.quantity))} ${esc(article?.unit||'m')}`;
  return `<article class="production-sequence-row sequence-row ${locked?'locked':''} ${taskInPeriod(t,ds)?'in-period':'outside-period'}" data-task="${t.id}" ${!locked?'draggable="true"':''}><span class="sequence-position" style="--machine-color:${machineColor(state,t.machineId)}">${index+1}</span><div class="sequence-copy" title="${esc(t.title)}${t.orderReference?' · Ordine '+esc(t.orderReference):''}"><button class="task-select" data-select-task="${t.id}" aria-pressed="${selectedTaskId===t.id}"><strong>${esc(taskReference(t))}</strong><span class="sequence-task-title">${esc(t.title)}</span></button><span class="sequence-state">${pendingRequest?'Interruzione richiesta · ':''}${t.status==='planned'?dispatchLabel(t):planningStateLabel(t)}${t.fixedStart?' · Data fissata':''}</span></div><span class="sequence-quantity">${quantity}</span><span class="sequence-duration">${mins(t.runMinutes+(t.effectiveSetupMinutes??t.setupMinutes))}</span><span class="sequence-start">${fmt(t.start)}</span><span class="sequence-end">${fmt(t.end)}</span><div class="sequence-row-actions"><button class="icon-button" data-move-task="${t.id}" data-direction="up" aria-label="Sposta prima ${esc(t.title)}" ${upDisabled?'disabled':''}>↑</button><button class="icon-button" data-move-task="${t.id}" data-direction="down" aria-label="Sposta dopo ${esc(t.title)}" ${downDisabled?'disabled':''}>↓</button>${!locked?`<button class="icon-button" data-unplan-task="${t.id}" aria-label="Togli dal piano ${esc(t.title)}" title="Togli dal piano">✕</button>`:''}${t.status==='in_progress'&&state.user.role==='admin'?`<button class="button danger subtle" data-request-interruption="${t.id}" ${pendingRequest?'disabled':''}>${pendingRequest?'Richiesta inviata':'Interrompi'}</button>`:''}<button class="card-menu" data-detail="${t.id}" aria-label="Dettagli ${esc(t.title)}">⋯</button></div></article>`;
}
function planning(){
  return overviewPlanning();
}

