  $('#prev-days').onclick=()=>{dateStart=addDays(dateStart,-planDays);resetTimeScroll();render();};$('#next-days').onclick=()=>{dateStart=addDays(dateStart,planDays);resetTimeScroll();render();};$('#go-today').onclick=()=>{dateStart=localDate();resetTimeScroll();render();};$('#date-start').onchange=e=>{if(e.target.value){dateStart=e.target.value;resetTimeScroll();render();}};$('#machine-filter').onchange=e=>{machineFilter=e.target.value;selectedTaskId=null;render();};$('#queue-search').oninput=e=>{search=e.target.value;listPage=0;const pos=e.target.selectionStart;render();$('#queue-search').focus();$('#queue-search').setSelectionRange(pos,pos);};
  $('#planning-search')?.addEventListener('click',()=>planningSearchDialog());$('#planning-outside')?.addEventListener('click',()=>planningSearchDialog(true));$('#clear-queue-filters')?.addEventListener('click',()=>{search='';machineFilter='';render();});bindPlanningLinks();
