  openDialog(`${dialogHeader(esc(t.title),`${esc(machine(t.machineId)?.name)} · ${esc(type(t.typeId)?.name)}`)}<div class="dialog-body">${badge(t.status)}${t.status==='planned'&&t.start&&t.start<localNow()?'<span class="badge cancelled">Inizio previsto superato</span>':''}${t.status==='planned'?`<span class="dispatch-state" data-tone="${dispatchTone(t)}">${esc(dispatchLabel(t))}</span>`:''}${interrupted?'<p class="selection-warning">Lavorazione interrotta e conservata nello storico: non è modificabile o ripristinabile.</p>':''}<div class="detail-grid"><div><span>Attrezzaggio</span><strong>${mins(t.effectiveSetupMinutes??t.setupMinutes)}</strong></div><div><span>Esecuzione</span><strong>${mins(t.runMinutes)}</strong></div><div><span>Inizio</span><strong>${fmt(t.start)}</strong></div><div><span>Fine</span><strong>${t.end?fmt(t.end):'Non pianificata'}</strong></div></div>${materialDetails(t)}${productionDetails(t)}${references}${t.notes?`<p class="notes">${esc(t.notes)}</p>`:''}${t.segments.length?`<details><summary>Fasi e giornate (${t.segments.length})</summary><div class="segment-list">${t.segments.map(s=>`<p><span>${s.kind==='setup'?'Attrezzaggio':'Esecuzione'}</span> ${fmt(s.start)} → ${fmt(s.end)}</p>`).join('')}</div></details>`:''}${!immutable&&t.status!=='cancelled'?`<form id="plan-task"><label>Posizione nella sequenza<select name="beforeId"><option value="">Alla fine della sequenza</option>${allowedPositions.map(x=>`<option value="${esc(x.id)}">Prima di: ${esc(x.title)}</option>`).join('')}</select></label>${protectedPositions?`<p class="notice">${protectedPositions} ${protectedPositions===1?'posizione protetta non è selezionabile':'posizioni protette non sono selezionabili'}.</p>`:''}<button type="submit" class="button primary">${t.status==='unplanned'?'Pianifica':'Sposta'}</button></form>`:''}<div class="detail-actions">${!immutable?`<button class="button secondary" id="edit-task">Modifica attività</button>`:''}${t.status==='planned'?`<a class="button secondary" href="/bordo-macchina?machine=${esc(t.machineId)}">Apri bordo macchina</a><button class="button subtle" id="unplan-task">Togli dal piano</button>`:''}${t.status==='in_progress'?`<a class="button primary" href="/bordo-macchina?machine=${esc(t.machineId)}">Rileva fasi al bordo macchina</a>`:''}${!immutable&&['planned','unplanned'].includes(t.status)?'<button class="button danger" data-state="cancelled">Annulla attività</button>':''}${!immutable&&t.status==='cancelled'?'<button class="button secondary" data-state="unplanned">Ripristina attività</button>':''}</div></div>`);
  $('#edit-task',modal)?.addEventListener('click',()=>{modal.close();editEntity('task',id,{onDiscard:()=>taskDetails(id)});});$('#plan-task',modal)?.addEventListener('submit',async e=>{e.preventDefault();try{await mutate({kind:'plan',id,beforeId:new FormData(e.target).get('beforeId')});}catch(err){toast(err.message,true);}});$('#unplan-task',modal)?.addEventListener('click',()=>mutate({kind:'plan',id,unplan:true}).catch(e=>toast(e.message,true)));document.querySelectorAll('[data-state]',modal).forEach(b=>b.onclick=()=>mutate({kind:'status',id,status:b.dataset.state},true).catch(e=>toast(e.message,true)));
