function taskReferences(t){const values=[t.orderReference&&`Ord. ${t.orderReference}`,t.outputLot&&`Lotto ${t.outputLot}`,t.dueDate&&`Consegna ${t.dueDate}`].filter(Boolean),label=values.join(' · ');if(!label)return '';return `<details class="task-references"><summary title="${esc(label)}">${esc(label)}</summary><dl>${t.orderReference?`<div><dt>Ordine</dt><dd>${esc(t.orderReference)}</dd></div>`:''}${t.outputLot?`<div><dt>Lotto</dt><dd>${esc(t.outputLot)}</dd></div>`:''}${t.dueDate?`<div><dt>Consegna</dt><dd>${esc(t.dueDate)}</dd></div>`:''}</dl></details>`;}
function taskMachine(t){const full=machine(t.machineId)?.name||'Macchina non disponibile',[code,...rest]=full.split(/\s+·\s+/),description=rest.join(' · ');return `<strong ${description?`title="${esc(description)}"`:''}>${esc(code)}</strong>`;}
function taskProduct(t){const code=t.productCode||'Da specificare',description=t.productDescription||'';return `<strong ${description?`title="${esc(description)}"`:''}>${esc(code)}</strong>`;}
function entityView(){const config={tasks:['Attività','','task'],machines:['Macchine','','machine'],types:['Tipologie','','type'],users:['Utenti','','user']}[view];const admin=state.user.role==='admin';let rows='',head='';
if(view==='tasks'){head='<th>Attività</th><th>Stato</th><th>Macchina</th><th>Tempi</th><th>Componenti consumati</th><th>Articolo prodotto</th><th>Inizio / fine</th><th>Azioni</th>';rows=pageItems(state.tasks.filter(t=>matchesTask(t,search)&&(!statusFilter||t.status===statusFilter)&&(!machineFilter||t.machineId===machineFilter))).map(t=>`<tr><td class="task-primary"><strong>${esc(t.title)}</strong><div class="task-primary-meta"><span class="task-type" style="--task-color:${esc(type(t.typeId)?.color)}" title="${esc(type(t.typeId)?.name)}">${esc(type(t.typeId)?.name)}</span>${taskReferences(t)}</div></td><td><div class="task-state-stack">${badge(t.status)}${t.status==='planned'&&t.start&&t.start<localNow()?'<span class="badge cancelled">Inizio previsto superato</span>':''}${t.status==='planned'?`<span class="dispatch-state" data-tone="${dispatchTone(t)}">${esc(dispatchLabel(t))}</span>`:''}</div></td><td class="task-machine">${taskMachine(t)}</td><td class="task-times"><span>${mins(t.runMinutes)}</span><small>Attr. ${mins(t.effectiveSetupMinutes??t.setupMinutes)}</small></td><td class="materials-column"><details class="table-materials"><summary><span>${esc(t.component1Code||'Da specificare')}</span><span>${esc(t.component2Code||'Da specificare')}</span></summary><p>${esc(t.component1Description)}</p><p>${esc(t.component2Description)}</p></details></td><td class="product-column">${taskProduct(t)}</td><td class="task-dates">${t.start?`${fmt(t.start)}<small>${fmt(t.end)}</small>`:'—'}</td><td><div class="row-actions"><button data-detail="${t.id}" class="button subtle">Apri</button>${!['in_progress','completed'].includes(t.status)?`<button data-edit="task:${t.id}" class="button subtle">Modifica</button><button data-delete="task:${t.id}" class="button danger subtle">Elimina</button>`:''}</div></td></tr>`).join('');}
if(view==='machines'){head='<th>Macchina</th><th>Descrizione</th><th>Velocità</th><th>Inizio pianificazione</th><th>Attività</th><th>Azioni</th>';rows=pageItems(state.machines).map(m=>`<tr><td><strong>${esc(m.name)}</strong></td><td>${esc(m.description)}</td><td>${m.speed} ${unitLabel(m.speedUnit)} / min</td><td>${fmt(m.anchor)}</td><td>${state.tasks.filter(t=>t.machineId===m.id).length}</td><td>${admin?rowActions('machine',m.id):'Solo lettura'}</td></tr>`).join('');}
if(view==='types'){head='<th>Tipologia</th><th>Colore</th><th>Attività</th><th>Azioni</th>';rows=pageItems(state.types).map(t=>`<tr><td><strong>${esc(t.name)}</strong></td><td><span class="color-swatch" style="background:${esc(t.color)}"></span> ${esc(t.color)}</td><td>${state.tasks.filter(x=>x.typeId===t.id).length}</td><td>${admin?rowActions('type',t.id):'Solo lettura'}</td></tr>`).join('');}
if(view==='users'){head='<th>Nome</th><th>Nome utente</th><th>Ruolo</th><th>Azioni</th>';rows=pageItems(state.users).map(u=>`<tr><td><strong>${esc(u.name)}</strong>${state.users.some(other=>other.id!==u.id&&other.name.trim().toLocaleLowerCase('it')===u.name.trim().toLocaleLowerCase('it'))?'<small class="notice">Nome duplicato: identifica la persona</small>':''}${u.id===state.user.id?'<small>Il tuo account</small>':''}</td><td>${esc(u.username)}</td><td><span class="badge">${u.role==='admin'?'Amministratore':'Operatore'}</span></td><td>${rowActions('user',u.id)}</td></tr>`).join('');}
return `${heading(config[0],config[1],admin||view==='tasks'?`<button class="button primary" data-new="${config[2]}">${icon('plus')} ${view==='tasks'?'Nuova attività':view==='machines'?'Nuova macchina':view==='types'?'Nuova tipologia':'Nuovo utente'}</button>`:'')}${view==='tasks'?`<div class="table-toolbar"><input id="task-search" placeholder="Cerca attività o codice…" value="${esc(search)}" aria-label="Cerca attività"><select id="status-filter" aria-label="Filtra stato">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${statusFilter===k?'selected':''}>${v}</option>`).join('')}<option value="" ${!statusFilter?'selected':''}>Tutti gli stati</option></select><select id="machine-filter" aria-label="Filtra macchina">${options(state.machines,machineFilter,'Tutte le macchine')}</select></div>`:''}<div class="table-wrap"><table class="${view==='tasks'?'task-table':''}"><thead><tr>${head}</tr></thead><tbody>${rows||`<tr><td colspan="8" class="empty-small">Nessun elemento da mostrare.</td></tr>`}</tbody></table></div>${view==='users'?'<p class="notice">Gli operatori gestiscono attività e pianificazione. Gli amministratori gestiscono anche macchine, tipologie, calendario e utenti.</p>':''}`;}
function rowActions(kind,id){return `<div class="row-actions"><button class="button subtle" data-edit="${kind}:${id}">Modifica</button><button class="button danger subtle" data-delete="${kind}:${id}">Elimina</button></div>`;}
function bindEntities(){for(const execution of state.executions||[])if(execution.interruptedAt){document.querySelector(`[data-edit="task:${execution.taskId}"]`)?.remove();document.querySelector(`[data-delete="task:${execution.taskId}"]`)?.remove();}document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editEntity(...b.dataset.edit.split(':')));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteEntity(...b.dataset.delete.split(':')));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>taskDetails(b.dataset.detail));$('#status-filter')?.addEventListener('change',e=>{statusFilter=e.target.value;listPage=0;render();});$('#machine-filter')?.addEventListener('change',e=>{machineFilter=e.target.value;listPage=0;render();});$('#task-search')?.addEventListener('input',e=>{search=e.target.value;listPage=0;const pos=e.target.selectionStart;render();$('#task-search').focus();$('#task-search').setSelectionRange(pos,pos);});}
function enhanceTaskMachineForm(){
  const x=taskFormContext||{},destination=$('[name="machineId"]',modal),ids=Array.isArray(x.compatibleMachineIds)&&x.compatibleMachineIds.length?x.compatibleMachineIds:[x.machineId||destination.value].filter(Boolean);
  destination.closest('label').firstChild.textContent='Macchina destinazione';
  const section=document.createElement('details');section.className='machine-compatibility';section.innerHTML=`<summary>Compatibilità con altre macchine</summary><p class="notice">Una sola macchina compatibile rende la destinazione automatica. Con più macchine puoi indicare quella preferita e cambiarla durante la pianificazione.</p><div class="compatibility-grid">${state.machines.map(m=>`<label><input type="checkbox" data-compatible-machine value="${m.id}" ${ids.includes(m.id)?'checked':''}>${esc(m.name)}</label>`).join('')}</div><input type="hidden" name="compatibleMachineIds" value="${esc(ids.join(','))}"><label>Macchina preferita<select name="preferredMachineId"><option value="">Nessuna preferenza</option>${state.machines.map(m=>`<option value="${m.id}" ${x.preferredMachineId===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label>`;
  $('.material-form',modal)?.before(section);
  const sync=()=>{const selected=[...modal.querySelectorAll('[data-compatible-machine]:checked')].map(i=>i.value);$('[name="compatibleMachineIds"]',modal).value=selected.join(',');};destination.onchange=()=>{const checkbox=modal.querySelector(`[data-compatible-machine][value="${CSS.escape(destination.value)}"]`);if(checkbox)checkbox.checked=true;sync();};
  section.querySelectorAll('[data-compatible-machine]').forEach(input=>input.onchange=sync);
}
function editEntity(kind,id,dialogOptions={}){if(['article','setupRule'].includes(kind)){editAdvanced(kind,id,dialogOptions);return;}const plural={task:'tasks',machine:'machines',type:'types',user:'users'};const x=state[plural[kind]].find(x=>x.id===id)||{};taskFormContext=kind==='task'?x:null;let fields='';const title={task:'attività',machine:'macchina',type:'tipologia',user:'utente'}[kind];
if(kind==='task'){if(!state.machines.length||!state.types.length){toast('Crea prima almeno una macchina e una tipologia.',true);return;}fields=`<section class="product-identity"><label>Prodotto da realizzare<select aria-label="Prodotto da realizzare" name="productArticleId" required>${articleOptions(x.productArticleId,'product')}</select></label><input type="hidden" name="title" value="${esc(x.title)}">${x.title?`<p class="notice">Denominazione esistente: ${esc(x.title)}</p>`:''}<p class="notice">Il nome della nuova lavorazione deriva dal prodotto selezionato.</p></section><div class="form-grid"><label>Tipologia<select name="typeId">${options(state.types,x.typeId)}</select></label><label>Macchina obbligatoria<select aria-label="Macchina" name="machineId">${options(state.machines,x.machineId)}</select></label><label>Attrezzaggio (minuti)<input name="setupMinutes" type="number" min="0" max="525600" step="1" required value="${x.setupMinutes??30}"></label><label>Esecuzione (minuti)<input name="runMinutes" type="number" min="1" max="525600" step="1" required value="${x.runMinutes??60}"></label></div>${materialForm(x)}${productionForm(x)}<details class="order-references" open><summary>Riferimenti ordine e lotto</summary><div class="form-grid"><label>Riferimento ordine<input name="orderReference" maxlength="120" value="${esc(x.orderReference)}"></label><label>Riferimento ERP<input name="erpReference" maxlength="120" value="${esc(x.erpReference)}"></label><label>Cliente<input name="customer" maxlength="200" value="${esc(x.customer)}"></label><label>Consegna prevista<input name="dueDate" type="date" value="${esc(x.dueDate)}"></label><label>Lotto prodotto previsto<input name="outputLot" maxlength="80" value="${esc(x.outputLot)}"></label></div><p class="notice">Il lotto effettivo viene verificato nella dichiarazione finale. I riferimenti ERP sono manuali.</p></details><label>Note<textarea name="notes" aria-label="Note" maxlength="2000" rows="3">${esc(x.notes)}</textarea></label><p class="notice">L’attrezzaggio viene eseguito una sola volta e deve rientrare interamente in una fascia lavorativa.</p>`;}
if(kind==='machine')fields=`<label>Nome macchina<input name="name" required maxlength="200" value="${esc(x.name)}"></label><label>Descrizione<input name="description" maxlength="500" value="${esc(x.description)}"></label><label>Inizio della pianificazione<input type="datetime-local" name="anchor" required value="${x.anchor||localDate()+'T08:00'}"></label><div class="form-grid"><label>Velocità macchina<input type="number" name="speed" required min="0.001" step="any" value="${x.speed??10}"></label><label>Unità della velocità<select name="speedUnit">${unitOptions(x.speedUnit||'m')}</select></label></div><p class="notice">La velocità è espressa in unità al minuto e viene usata per le attività con calcolo automatico.</p><p class="notice">Le attività si susseguono a partire da questa data, rispettando i giorni e le fasce lavorative.</p>`;
if(kind==='type')fields=`<label>Nome tipologia<input name="name" required maxlength="200" value="${esc(x.name)}"></label><label>Colore<input type="color" name="color" value="${x.color||'#2563eb'}"></label>`;
if(kind==='user')fields=`<label>Nome e cognome<input name="name" required maxlength="200" value="${esc(x.name)}"></label><label>Nome utente<input name="username" required maxlength="80" autocomplete="off" value="${esc(x.username)}"></label><label>Ruolo<select name="role"><option value="operator" ${x.role==='operator'?'selected':''}>Operatore</option><option value="admin" ${x.role==='admin'?'selected':''}>Amministratore</option></select></label><label>${id?'Nuova password (lascia vuoto per mantenerla)':'Password'}<input name="password" type="password" minlength="10" maxlength="200" ${id?'':'required'} autocomplete="new-password"></label><p class="notice">Almeno 10 caratteri. Cambiare la password disconnette le sessioni dell’utente.</p>`;
openDialog(`${dialogHeader(`${id?'Modifica':kind==='user'?'Nuovo':'Nuova'} ${title}`)}<form><div class="dialog-body">${fields}</div>${dialogFooter()}</form>`,async f=>{const values=Object.fromEntries(f);if(kind==='machine')values.speed=Number(values.speed);if(kind==='task'){values.setupMinutes=Number(values.setupMinutes);values.runMinutes=Number(values.runMinutes);values.quantity=values.quantity?Number(values.quantity):null;values.compatibleMachineIds=String(values.compatibleMachineIds||'').split(',').filter(Boolean);values.preferredMachineId=values.preferredMachineId||null;if(!values.compatibleMachineIds.length)throw new Error('Seleziona almeno una macchina compatibile.');if(!values.compatibleMachineIds.includes(values.machineId))throw new Error('La macchina destinazione deve essere tra quelle compatibili.');if(values.preferredMachineId&&!values.compatibleMachineIds.includes(values.preferredMachineId))throw new Error('La macchina preferita deve essere tra quelle compatibili.');}if(kind==='user'){await api('users',{id,...values});modal.close();await boot();toast('Utente salvato.');}else await mutate({kind,id,values});},{protectUnsaved:true,...dialogOptions});if(kind==='task')bindProductionForm();}
function deleteEntity(kind,id){openDialog(`${dialogHeader('Elimina elemento')}<form><div class="dialog-body"><p>Confermi l’eliminazione? Gli elementi utilizzati da altre entità e le attività bloccate sono protetti.</p></div>${dialogFooter('Elimina')}</form>`,async()=>{if(kind==='user'){await api('users',{id,remove:true});modal.close();await reload();toast('Utente eliminato.');}else await mutate({kind,id,remove:true});});}
function shiftInputs(shifts,prefix){return `<div class="shift-inputs">${[0,1].map(i=>`<div><input type="time" name="${prefix}-${i}-start" value="${shifts[i]?.[0]||''}" aria-label="Inizio fascia ${i+1}"><span>—</span><input type="time" name="${prefix}-${i}-end" value="${shifts[i]?.[1]||''}" aria-label="Fine fascia ${i+1}"></div>`).join('')}</div>`;}
function readShifts(f,prefix,working=true){if(!working)return [];const shifts=[];for(let i=0;i<2;i++){const start=f.get(`${prefix}-${i}-start`),end=f.get(`${prefix}-${i}-end`);if(!start&&!end)continue;if(!start||!end||start>=end)throw new Error('Completa ogni fascia con un inizio precedente alla fine.');shifts.push([start,end]);}if(!shifts.length)throw new Error('Indica almeno una fascia per un giorno lavorativo.');if(shifts.length===2&&shifts[1][0]<shifts[0][1])throw new Error('Le fasce non devono sovrapporsi e devono essere in ordine.');return shifts;}
function calendarView(){const admin=state.user.role==='admin';const first=calendarMonth+'-01',dow=new Date(first+'T12:00Z').getUTCDay(),gridStart=addDays(first,-((dow+6)%7));const exceptionMap=calendarScope==='global'?state.calendar.exceptions:(state.calendar.machineExceptions[calendarScope]||{});const cells=Array.from({length:42},(_,i)=>{const d=addDays(gridStart,i),outside=d.slice(0,7)!==calendarMonth;const shifts=calendarScope==='global'?(state.calendar.exceptions[d]??state.calendar.weekly[new Date(d+'T12:00Z').getUTCDay()]):effectiveShifts(d,calendarScope);return `<button class="calendar-day ${outside?'outside':''} ${!shifts?.length?'off':''} ${Object.hasOwn(exceptionMap,d)?'exception':''} ${d===localDate()?'today-cell':''}" data-day="${d}" ${!admin?'disabled':''}><span>${Number(d.slice(8))}</span><small>${shifts?.length?shifts.map(s=>s.join('–')).join('<br>'):'Non lavorativo'}</small>${Object.hasOwn(exceptionMap,d)?'<em>Eccezione</em>':''}</button>`;});return `${heading('Calendario di produzione','Una settimana standard, con eccezioni per data e per macchina.',admin?'<button class="button primary" id="bulk-exception">'+icon('plus')+' Imposta periodo</button><button class="button secondary" id="italian-holidays">Aggiungi festività italiane</button>':'')}<div class="calendar-layout"><section class="panel weekly"><div class="panel-heading"><h2>Settimana standard</h2><small>Comune a tutte le macchine</small></div><form id="weekly-form"><fieldset ${!admin?'disabled':''}><div class="weekly-labels"><span>Giorno lavorativo</span><span>Fascia 1 / Fascia 2</span></div><div class="weekly-days">${[1,2,3,4,5,6,0].map(day=>`<div class="weekly-row"><label class="check-label"><input type="checkbox" name="work-${day}" ${state.calendar.weekly[day]?.length?'checked':''}>${days[day]}</label>${shiftInputs(state.calendar.weekly[day]||[],`day-${day}`)}</div>`).join('')}</div><div class="weekly-actions"><button type="button" class="button secondary" id="bulk-week">Applica orari a più giorni</button><button class="button primary" type="submit">Salva settimana</button></div></fieldset></form><p class="notice">Le fasce vuote non sono utilizzate. Le eccezioni per data prevalgono sulla settimana standard.</p></section><section class="panel month-panel"><div class="month-toolbar"><button class="icon-button" id="prev-month" aria-label="Mese precedente">‹</button><h2>${new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(first+'T12:00Z'))}</h2><button class="icon-button" id="next-month" aria-label="Mese successivo">›</button><select id="calendar-scope" aria-label="Calendario macchina"><option value="global">Calendario generale</option>${options(state.machines,calendarScope)}</select></div><div class="month-grid">${[1,2,3,4,5,6,0].map(d=>`<div class="weekday">${days[d].slice(0,3)}</div>`).join('')}${cells.join('')}</div><div class="calendar-legend"><span>● Lavorativo</span><span>○ Non lavorativo</span><span class="amber">● Eccezione</span></div></section></div><details class="panel exceptions-panel"><summary>Eccezioni ${calendarScope==='global'?'generali':esc(machine(calendarScope)?.name)} · ${Object.keys(exceptionMap).length}</summary><p class="notice">Le eccezioni della macchina prevalgono su quelle generali.</p><div class="table-wrap"><table><thead><tr><th>Data</th><th>Disponibilità</th><th>Azioni</th></tr></thead><tbody>${Object.entries(exceptionMap).sort(([a],[b])=>a.localeCompare(b)).map(([date,shifts])=>`<tr><td>${new Intl.DateTimeFormat('it-IT',{dateStyle:'full',timeZone:'UTC'}).format(new Date(date+'T12:00Z'))}</td><td>${shifts.length?shifts.map(s=>s.join('–')).join(' / '):'<span class="badge cancelled">Non lavorativo</span>'}</td><td>${admin?`<div class="row-actions"><button data-ex-edit="${date}" class="button subtle">Modifica</button><button data-ex-remove="${date}" class="button danger subtle">Ripristina standard</button></div>`:'Solo lettura'}</td></tr>`).join('')||'<tr><td colspan="3" class="empty-small">Nessuna eccezione. Si applica il calendario generale.</td></tr>'}</tbody></table></div></details>`;}
function bindCalendar(){const changeMonth=n=>{const d=new Date(calendarMonth+'-01T12:00Z');d.setUTCMonth(d.getUTCMonth()+n);calendarMonth=d.toISOString().slice(0,7);render();};$('#prev-month').onclick=()=>changeMonth(-1);$('#next-month').onclick=()=>changeMonth(1);$('#calendar-scope').value=calendarScope;$('#calendar-scope').onchange=e=>{calendarScope=e.target.value;render();};$('#weekly-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),cal=structuredClone(state.calendar);try{for(let i=0;i<7;i++)cal.weekly[i]=readShifts(f,`day-${i}`,f.has(`work-${i}`));await mutate({kind:'calendar',values:cal},true);}catch(err){toast(err.message,true);}};$('#bulk-week')?.addEventListener('click',bulkWeek);$('#bulk-exception')?.addEventListener('click',()=>exceptionDialog());$('#italian-holidays')?.addEventListener('click',holidayDialog);document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>exceptionDialog(b.dataset.day));document.querySelectorAll('[data-ex-edit]').forEach(b=>b.onclick=()=>exceptionDialog(b.dataset.exEdit));document.querySelectorAll('[data-ex-remove]').forEach(b=>b.onclick=()=>{const cal=structuredClone(state.calendar);const map=calendarScope==='global'?cal.exceptions:cal.machineExceptions[calendarScope];delete map[b.dataset.exRemove];mutate({kind:'calendar',values:cal},true).catch(e=>toast(e.message,true));});}
function holidayDialog(){const year=Number(calendarMonth.slice(0,4));openDialog(`${dialogHeader('Aggiungi festività italiane',String(year))}<form><div class="dialog-body"><p>Le festività saranno aggiunte come chiusure generali modificabili. Le eccezioni già presenti e quelle delle macchine hanno precedenza.</p><ul>${Object.entries(italianHolidays(year)).sort(([a],[b])=>a.localeCompare(b)).map(([date,name])=>`<li>${esc(date)} · ${esc(name)}</li>`).join('')}</ul><p class="notice">Festa patronale e chiusure aziendali si impostano con Imposta periodo. Le variazioni alle attività saranno mostrate prima del salvataggio.</p></div>${dialogFooter('Verifica le nuove date')}</form>`,async()=>mutate({kind:'calendar',values:addItalianHolidays(state.calendar,year)},true));}
function dayChecks(prefix){return `<div class="day-checks">${[1,2,3,4,5,6,0].map(d=>`<label class="check-label"><input type="checkbox" name="${prefix}-${d}" ${d!==0&&d!==6?'checked':''}>${days[d].slice(0,3)}</label>`).join('')}</div>`;}
function bulkWeek(){openDialog(`${dialogHeader('Applica orari a più giorni','Seleziona i giorni della settimana da aggiornare.')}<form><div class="dialog-body">${dayChecks('select')}<label class="check-label"><input type="checkbox" name="working" checked>Giorni lavorativi</label>${shiftInputs([['08:00','12:00'],['13:00','17:00']],'bulk')}</div>${dialogFooter('Applica')}</form>`,async f=>{const cal=structuredClone(state.calendar),shifts=readShifts(f,'bulk',f.has('working'));let n=0;for(let i=0;i<7;i++)if(f.has(`select-${i}`)){cal.weekly[i]=shifts;n++;}if(!n)throw new Error('Seleziona almeno un giorno.');await mutate({kind:'calendar',values:cal},true);},{protectUnsaved:true});}
function exceptionDialog(date){const shifts=date?(calendarScope==='global'?(state.calendar.exceptions[date]??state.calendar.weekly[new Date(date+'T12:00Z').getUTCDay()]):baseShifts(date,calendarScope)):[['08:00','12:00'],['13:00','17:00']];openDialog(`${dialogHeader(date?'Eccezione del giorno':'Imposta un periodo','Modifica giorni lavorativi e fasce per una data o un intervallo.')}<form><div class="dialog-body"><label>Ambito<select name="scope"><option value="global">Tutte le macchine</option>${options(state.machines,calendarScope)}</select></label><div class="form-grid"><label>Dal<input type="date" name="from" required value="${date||calendarMonth+'-01'}"></label><label>Al<input type="date" name="to" required value="${date||calendarMonth+'-01'}"></label></div>${date?'':dayChecks('select')}<label class="check-label"><input type="checkbox" name="working" ${shifts.length?'checked':''}>Giorno lavorativo</label>${shiftInputs(shifts,'ex')}<p class="notice">Per una chiusura, deseleziona “Giorno lavorativo”. Puoi impostare fino a 366 giorni per volta.</p></div>${dialogFooter('Salva eccezioni')}</form>`,async f=>{const from=f.get('from'),to=f.get('to');if(from>to)throw new Error('La data finale deve seguire quella iniziale.');const count=(new Date(to+'T12:00Z')-new Date(from+'T12:00Z'))/86400000+1;if(count>366)throw new Error('Seleziona un periodo massimo di 366 giorni.');const cal=structuredClone(state.calendar),scope=f.get('scope'),map=scope==='global'?cal.exceptions:(cal.machineExceptions[scope]??={}),ss=readShifts(f,'ex',f.has('working'));let n=0;for(let i=0;i<count;i++){const d=addDays(from,i);if(date||f.has(`select-${new Date(d+'T12:00Z').getUTCDay()}`)){map[d]=ss;n++;}}if(!n)throw new Error('Nessuna data corrisponde ai giorni selezionati.');await mutate({kind:'calendar',values:cal},true);},{protectUnsaved:true});$('select[name=scope]',modal).value=calendarScope;}
setInterval(async()=>{if(!state||modal.open||dragging||dragSavePending)return;try{const endpoint=stateEndpoint(),latest=await api(endpoint);if(endpoint!==stateEndpoint())return;if(latest.revision!==state.revision){state=latest;render();toast('Piano aggiornato con le modifiche del reparto.');}else if(view==='planning'&&JSON.stringify([...planningWarnings(state)])!==warningSignature)render();}catch{}},15000);
boot();

function unitLabel(unit){return {m:'m lineari',m2:'m²',kg:'kg'}[unit]||unit;}
function quantityCaption(t){const article=state.articles?.find(a=>a.id===t.productArticleId);return t.quantity?`<small class="quantity-caption">${t.quantity} ${unitLabel(article?.unit||'m')} · ${t.calculationMode==='automatic'?'Tempo automatico':'Tempo manuale'}</small>`:'';}
function durationChanges(c){return `${c.oldRunMinutes!==undefined&&c.oldRunMinutes!==c.runMinutes?`<p>Esecuzione: ${mins(c.oldRunMinutes)} → <b>${mins(c.runMinutes)}</b></p>`:''}${c.oldSetupMinutes!==undefined&&c.oldSetupMinutes!==c.setupMinutes?`<p>Attrezzaggio: ${mins(c.oldSetupMinutes)} → <b>${mins(c.setupMinutes)}</b></p>`:''}`;}
function unitOptions(unit){return ['m','m2','kg'].map(v=>`<option value="${v}" ${unit===v?'selected':''}>${unitLabel(v)} / min</option>`).join('');}
function articleOptions(id,kind){return `<option value="">Seleziona un articolo…</option>${(state.articles||[]).filter(a=>a.kind===kind||a.kind==='both'||a.id===id).map(a=>`<option value="${esc(a.id)}" ${a.id===id?'selected':''}>${esc(a.code)} · ${esc(a.description)} (${unitLabel(a.unit)})</option>`).join('')}`;}
function productionForm(t){return `<section class="production-form"><h3>Quantità e tempo di esecuzione</h3><div class="form-grid"><label>Quantità da produrre<input name="quantity" type="number" min="0.001" max="1000000000" step="any" value="${t.quantity??''}" placeholder="Es. 1200"></label><label>Calcolo del tempo<select aria-label="Calcolo del tempo" name="calculationMode"><option value="manual" ${t.calculationMode!=='automatic'?'selected':''}>Tempo manuale</option><option value="automatic" ${t.calculationMode==='automatic'?'selected':''}>Quantità ÷ velocità macchina</option></select></label></div><p class="calculation-summary" id="calculation-summary" aria-live="polite"></p><p class="notice">Il tempo automatico è arrotondato al minuto superiore. Unità dell’articolo e della velocità devono coincidere. L’attrezzaggio è aggiunto separatamente.</p></section>`;}
function bindProductionForm(){const f=$('form',modal);const initialProduct=f.elements.productArticleId.value;const initialTitle=f.elements.title.value;f.elements.productArticleId.addEventListener('change',()=>{const a=state.articles.find(a=>a.id===f.elements.productArticleId.value);f.elements.title.value=f.elements.productArticleId.value===initialProduct&&initialTitle?initialTitle:(a?.description||'');});const update=()=>{const mode=f.elements.calculationMode.value,qty=f.elements.quantity,run=f.elements.runMinutes,m=machine(f.elements.machineId.value),article=state.articles.find(a=>a.id===f.elements.productArticleId.value);qty.required=mode==='automatic';run.readOnly=mode==='automatic';const summary=$('#calculation-summary',modal);if(mode==='manual'){summary.textContent='Tempo di esecuzione inserito manualmente.';return;}if(!article){summary.textContent='Seleziona l’articolo prodotto per verificare l’unità di misura.';return;}if(article.unit!==m.speedUnit){summary.textContent=`Unità incompatibili: articolo in ${unitLabel(article.unit)}, macchina in ${unitLabel(m.speedUnit)} / min.`;return;}const q=Number(qty.value);if(q>0&&m.speed>0){const minutes=Math.ceil(q/m.speed);run.value=minutes;summary.textContent=`${q} ${unitLabel(article.unit)} ÷ ${m.speed} ${unitLabel(m.speedUnit)} / min = ${mins(minutes)} di esecuzione.`;}else summary.textContent='Inserisci la quantità da produrre.';};for(const name of ['quantity','calculationMode','machineId','productArticleId'])f.elements[name].addEventListener('input',update);update();}
function productionDetails(t){const a=state.articles?.find(x=>x.id===t.productArticleId);return `<div class="detail-grid"><div><span>Quantità da produrre</span><strong>${t.quantity!==null&&t.quantity!==undefined?`${t.quantity} ${unitLabel(a?.unit||'m')}`:'Non indicata'}</strong></div><div><span>Calcolo esecuzione</span><strong>${t.calculationMode==='automatic'?'Quantità ÷ velocità':'Tempo manuale'}</strong></div><div><span>Attrezzaggio base</span><strong>${mins(t.setupMinutes)}</strong></div><div><span>Attrezzaggio applicato</span><strong>${mins(t.effectiveSetupMinutes??t.setupMinutes)}</strong></div></div>`;}
function advancedView(){const articles=view==='articles',admin=state.user.role==='admin',items=articles?state.articles:state.setupRules;const title=articles?'Anagrafica articoli':'Regole di attrezzaggio',kind=articles?'article':'setupRule';const rows=pageItems((items||[]).filter(x=>!articles||!search||[x.code,x.description].some(v=>v.toLowerCase().includes(search.toLowerCase())))).map(x=>articles?`<tr><td><strong class="article-code">${esc(x.code)}</strong></td><td class="article-description">${esc(x.description)}</td><td>${unitLabel(x.unit)}</td><td>${{component:'Componente',product:'Articolo prodotto',both:'Componente e prodotto'}[x.kind]}</td><td>${admin?rowActions(kind,x.id):'Solo lettura'}</td></tr>`:`<tr><td>${esc(machine(x.machineId)?.name)}</td><td>${esc(type(x.fromTypeId)?.name)}</td><td>${esc(type(x.toTypeId)?.name)}</td><td><strong>${mins(x.minutes)}</strong></td><td>${admin?rowActions(kind,x.id):'Solo lettura'}</td></tr>`).join('');return `${heading(title,articles?'Codici, descrizioni e unità di misura condivisi tra le attività.':'Definisci il tempo di preparazione passando da una lavorazione alla successiva.',admin?`<button class="button primary" data-new="${kind}">${icon('plus')} ${articles?'Nuovo articolo':'Nuova regola'}</button>`:'')}${articles?`<div class="table-toolbar"><input id="task-search" placeholder="Cerca codice o descrizione…" aria-label="Cerca articolo" value="${esc(search)}"></div>`:''}<div class="table-wrap"><table><thead><tr>${articles?'<th>Codice</th><th>Descrizione</th><th>Unità</th><th>Uso</th><th>Azioni</th>':'<th>Macchina</th><th>Lavorazione precedente</th><th>Lavorazione successiva</th><th>Attrezzaggio</th><th>Azioni</th>'}</tr></thead><tbody>${rows||'<tr><td colspan="5" class="empty-small">Nessun elemento. Aggiungine uno per iniziare.</td></tr>'}</tbody></table></div><p class="notice">${articles?'Gli articoli utilizzati non possono essere eliminati. Codici e descrizioni delle attività non bloccate seguono l’anagrafica; le attività in corso e completate conservano i dati storici.':'La regola sostituisce il tempo base dell’attività quando le due tipologie si susseguono sulla macchina scelta. La prima attività e i passaggi senza regola usano il tempo base. Le attività bloccate mantengono l’attrezzaggio già applicato.'}</p>`;}
function editAdvanced(kind,id,dialogOptions={}){const article=kind==='article',items=article?state.articles:state.setupRules,x=items.find(t=>t.id===id)||{};if(!article&&(!state.types.length||!state.machines.length)){toast('Crea prima una macchina e una tipologia.',true);return;}const fields=article?`<label>Codice articolo<input name="code" required maxlength="80" value="${esc(x.code)}"></label><label>Descrizione articolo<input name="description" required maxlength="200" value="${esc(x.description)}"></label><label>Descrizione inglese (facoltativa)<input name="descriptionEn" maxlength="200" value="${esc(x.descriptionEn)}"></label><div class="form-grid"><label>Unità di misura<select name="unit">${['m','m2','kg'].map(v=>`<option value="${v}" ${x.unit===v?'selected':''}>${unitLabel(v)}</option>`).join('')}</select></label><label>Utilizzo<select aria-label="Utilizzo" name="kind"><option value="component" ${x.kind==='component'?'selected':''}>Componente</option><option value="product" ${x.kind==='product'?'selected':''}>Articolo prodotto</option><option value="both" ${x.kind==='both'?'selected':''}>Componente e prodotto</option></select></label></div>`:`<label>Macchina<select aria-label="Macchina" name="machineId">${options(state.machines,x.machineId)}</select></label><label>Lavorazione precedente<select aria-label="Lavorazione precedente" name="fromTypeId">${options(state.types,x.fromTypeId)}</select></label><label>Lavorazione successiva<select aria-label="Lavorazione successiva" name="toTypeId">${options(state.types,x.toTypeId)}</select></label><label>Attrezzaggio del passaggio (minuti)<input name="minutes" type="number" required min="0" max="525600" step="1" value="${x.minutes??15}"></label><p class="notice">La modifica ricalcola la sequenza della macchina. Controlla l’anteprima prima di confermare.</p>`;openDialog(`${dialogHeader(`${id?'Modifica':article?'Nuovo':'Nuova'} ${article?'articolo':'regola'}`)}<form><div class="dialog-body">${fields}</div>${dialogFooter()}</form>`,async f=>{const values=Object.fromEntries(f);if(!article)values.minutes=Number(values.minutes);await mutate({kind,id,values},true);},{protectUnsaved:true,...dialogOptions});}

function shopContext(){return {state,esc,icon,localDate,addDays,fmt,mins,unitLabel,machine,type,materialDetails,openDialog,dialogHeader,dialogFooter,api,reload,toast,render};}

function reasonCatalogView(){const scrap=view==='scrapReasons',admin=state.user.role==='admin',items=state[view]||[];return `${heading(scrap?'Causali scarto':'Causali fermo macchina','Le causali attive sono selezionabili dagli operatori. Le dichiarazioni conservano la descrizione originale.',admin?'<button class="button primary" id="new-cause">Nuova causale</button>':'')}<div class="table-wrap"><table><thead><tr><th>Codice</th><th>Descrizione italiana</th><th>Descrizione inglese</th><th>Stato</th><th>Azioni</th></tr></thead><tbody>${pageItems(items).map(x=>`<tr><td><strong>${esc(x.code)}</strong></td><td>${esc(x.description)}</td><td>${esc(x.descriptionEn||x.description)}</td><td>${x.active?'Attiva':'Disattivata'}</td><td>${admin?`<button class="button subtle" data-edit-cause="${esc(x.id)}">Modifica</button><button class="button subtle" data-toggle-cause="${esc(x.id)}">${x.active?'Disattiva':'Attiva'}</button><button class="button danger" data-remove-cause="${esc(x.id)}">Elimina</button>`:'Solo lettura'}</td></tr>`).join('')||'<tr><td colspan="5">Nessuna causale disponibile.</td></tr>'}</tbody></table></div><p class="notice">Una causale già utilizzata può essere disattivata. Rimarrà nello storico ma non verrà proposta per nuove registrazioni.</p>`;}
function reasonEndpoint(){return view==='scrapReasons'?'scrap-reasons':'machine-stop-reasons';}
function bindReasonCatalog(){const items=state[view]||[];$('#new-cause')?.addEventListener('click',()=>editReason());document.querySelectorAll('[data-edit-cause]').forEach(b=>b.onclick=()=>editReason(b.dataset.editCause));document.querySelectorAll('[data-toggle-cause]').forEach(b=>b.onclick=async()=>{const x=items.find(x=>x.id===b.dataset.toggleCause);b.disabled=true;try{await api(reasonEndpoint(),{revision:state.revision,...x,active:!x.active});await reload();}catch(e){toast(e.message,true);b.disabled=false;}});document.querySelectorAll('[data-remove-cause]').forEach(b=>b.onclick=()=>{const x=items.find(x=>x.id===b.dataset.removeCause),endpoint=reasonEndpoint();openDialog(`${dialogHeader('Elimina causale')}<form><div class="dialog-body"><p>${esc(x.code)} · ${esc(x.description)}</p></div>${dialogFooter('Elimina')}</form>`,async()=>{await api(endpoint,{revision:state.revision,id:x.id,remove:true});modal.close();await reload();});});}
function editReason(id){const x=(state[view]||[]).find(x=>x.id===id)||{},endpoint=reasonEndpoint();openDialog(`${dialogHeader(id?'Modifica causale':'Nuova causale')}<form><div class="dialog-body"><label>Codice<input name="code" maxlength="40" required value="${esc(x.code)}"></label><label>Descrizione italiana<input name="description" maxlength="200" required value="${esc(x.description)}"></label><label>Descrizione inglese<input name="descriptionEn" maxlength="200" value="${esc(x.descriptionEn)}"></label><label>Stato<select name="active"><option value="true" ${x.active!==false?'selected':''}>Attiva</option><option value="false" ${x.active===false?'selected':''}>Disattivata</option></select></label></div>${dialogFooter()}</form>`,async f=>{await api(endpoint,{revision:state.revision,id,...Object.fromEntries(f),active:f.get('active')==='true'});modal.close();await reload();toast('Causale salvata.');},{protectUnsaved:true});}

function timeContext(){return {state,esc,fmt,mins,machine,type,labels,unitLabel,toast,effectiveShifts,baseShifts,canDrag:()=>!dragSavePending,dragMode:()=>planDragMode,previewPlacement:action=>api('preview',{revision:state.revision,action}),setDragState:(id,offset=0)=>{dragging=Boolean(id);dragTaskId=id;dragGrabOffsetMinutes=offset;},onTouchDrop:action=>saveDraggedPlan(action).catch(error=>toast(error.message,true)),selectedTaskId,zoom:planZoom,planWarnings:planningWarnings(state),dragTaskId:()=>dragTaskId,dragGrabOffsetMinutes:()=>dragGrabOffsetMinutes};}
function machineStopDialog(id,action){const stop=(state.machineStops||[]).find(x=>x.machineId===id&&!x.endedAt);openDialog(`${dialogHeader(action==='stop'?'Ferma macchina':'Riattiva macchina',esc(machine(id)?.name))}<form><div class="dialog-body">${action==='stop'?`<label>Motivo del fermo<select name="reasonId" required><option value="">Seleziona una causale</option>${(state.machineStopReasons||[]).filter(x=>x.active).map(x=>`<option value="${esc(x.id)}">${esc(x.code)} · ${esc(x.description)}</option>`).join('')}</select></label><p class="notice">La lavorazione attiva sarà sospesa. Non potranno iniziare nuove fasi. La durata del fermo resta aperta: le date del piano dovranno essere verificate alla ripresa. Termina prima un eventuale attrezzaggio in corso.</p>`:`<p>Fermo: ${esc(stop?.reason)}</p><p class="notice">La macchina torna disponibile. La lavorazione sospesa richiede una ripresa esplicita al bordo macchina. Verifica il piano prima di procedere.</p>`}<h3>Ultimi fermi</h3>${(state.machineStops||[]).filter(x=>x.machineId===id).slice(0,5).map(x=>`<p>${esc(x.reason)} · ${esc(x.startedAt)} → ${esc(x.endedAt||'In corso')}</p>`).join('')||'<p>Nessun fermo registrato.</p>'}</div>${dialogFooter('Conferma')}</form>`,async f=>{await api('machine-stop',{revision:state.revision,machineId:id,action,reasonId:f.get('reasonId')||null});modal.close();await reload();toast('Stato macchina aggiornato.');});}

function mesContext(){const active=view;return {state,view,esc,unitLabel,heading,api,render,reload,toast,openDialog,dialogHeader,dialogFooter,isActive:()=>view===active};}
function statisticsContext(){return {state,esc,localDate,unitLabel,heading,api,render,toast,openDialog,dialogHeader,isActive:()=>view==='statistics'};}

function plannerControlContext(){return {state,selectedTaskId,dateStart,esc,badge,fmt,mins,machine,type,unitLabel,materialDetails,taskDetails,mutate,toast,warnings:planningWarnings(state),clear:clearPlanningSelection,focusTask:()=>{const t=state.tasks.find(t=>t.id===selectedTaskId);if(!t?.start)return;machineFilter=t.machineId;selectedResourceId=t.machineId;dateStart=t.start.slice(0,10);planDays=1;localStorage.setItem('aloven-plan-view','day');resetTimeScroll();render();revealPlannedTask(t.id);}};}
function selectPlanningTask(id,focusPanel=false){const task=state.tasks.find(t=>t.id===id);if(!task)return;plannerReturnFocus=document.activeElement;selectedTaskId=id;refreshPlanningSelection();if(focusPanel||matchMedia('(max-width:1100px)').matches)$('#selection-heading')?.focus();}
function clearPlanningSelection(){const returnFocus=plannerReturnFocus,id=selectedTaskId;selectedTaskId=null;refreshPlanningSelection();const fallback=[...document.querySelectorAll('[data-select-task],.time-block[data-task]')].find(b=>(b.dataset.selectTask||b.dataset.task)===id);(returnFocus?.isConnected?returnFocus:fallback)?.focus();}
function refreshPlanningSelection(){const panel=$('#planning-selection');if(!panel)return;$('.planner-area,.essential-planner')?.classList.toggle('has-selection',Boolean(selectedTaskId));panel.hidden=!selectedTaskId;panel.innerHTML=planningSelection(plannerControlContext());document.querySelectorAll('.task-card[data-task],.time-block[data-task],.planning-candidate[data-task],.production-sequence-row[data-task]').forEach(b=>{const chosen=b.dataset.task===selectedTaskId;b.classList.toggle('selected',chosen);if(b.matches('button')){if(chosen)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current');}});document.querySelectorAll('[data-select-task]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.selectTask===selectedTaskId)));bindPlanningSelection(plannerControlContext());}
